def r2_esc(v):return html.escape(str(v),quote=True)
def r2_header(universe):
    logo={'music':MUSIC,'engineering':ENGINEERING}.get(universe,CORP)
    label={'music':'MPBP MUSIC','engineering':'MPBP ENGINEERING'}.get(universe,'MPBP 440 CORP.')
    sub={'music':'Music Entertainment','engineering':'Design & Software Engineering'}.get(universe,'Art · Technologie · Création')
    navigation=[('index.html','Entreprise','corporate'),('musique.html','Music','music'),('engineering.html','Engineering','engineering')]
    if universe=='engineering':navigation=[('engineering.html','Découvrir','engineering'),('engineering.html#projets','Projets','projects'),('boutique.html','Boutique','shop'),('demos.html','Démos & essais','demos')]
    return f'''<a class="skip" href="#main">Aller au contenu</a><div class="review">Revue V15 · Direction révisée <a href="review.html">Voir les écrans</a></div><header class="header"><div class="wrap header-inner"><a class="brand brand-{universe}" href="{'engineering.html' if universe=='engineering' else 'index.html'}"><span class="brand-image"><img src="{logo}" alt="{label} — {'logo validé' if universe=='engineering' else 'logo officiel'}" width="120" height="80"></span><span><strong>{label}</strong><small>{sub}</small></span></a><button class="menu" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="nav" id="navigation" aria-label="Navigation principale">'''+''.join(f'<a href="{url}">{name}</a>' for url,name,key in navigation)+f'<a class="contact-link" href="{MAIL}">Contact</a></nav></div></header>'
def r2_footer():return f'''<footer class="footer"><div class="wrap footer-top"><a class="footer-identity" href="index.html"><img src="{CORP}" alt="MPBP 440 Corp." width="150" height="100"><span>Une entreprise indépendante.<br>Des univers à créer.</span></a><nav class="footer-links" aria-label="Navigation secondaire"><a href="index.html">Entreprise</a><a href="musique.html">MPBP Music</a><a href="engineering.html">Engineering</a><a href="boutique.html">Boutique</a><a href="demos.html">Démos & essais</a><a href="{MAIL}">Contact</a></nav></div><div class="wrap footer-inner"><p>© 2026 MPBP 440 Corp.</p><p>Revue locale · Aucun logiciel en vente actuellement.</p></div></footer>'''
def r2_page(file,title,universe,body):
    icon={'music':MUSIC,'engineering':ENGINEERING}.get(universe,CORP)
    document=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>{r2_esc(title)} · MPBP 440 Corp. · Revue V15</title><meta name="theme-color" content="#050a10"><link rel="icon" href="{icon}"><link rel="stylesheet" href="site.css"><link rel="stylesheet" href="premium-r2.css"><script src="site.js" defer></script><script src="engineering-content.js" defer></script></head><body class="{universe} r2">{r2_header(universe)}<main id="main">{body}</main>{r2_footer()}</body></html>'''
    document=document.replace('</head>','<link rel="stylesheet" href="corporate-update.css"></head>')
    if '/' in file:
        document=document.replace('href="corporate-update.css"','href="../corporate-update.css"')
        document=document.replace('href="site.css"','href="../site.css"').replace('href="premium-r2.css"','href="../premium-r2.css"').replace('src="site.js"','src="../site.js"').replace('src="engineering-content.js"','src="../engineering-content.js"')
        for target in ('index.html','musique.html','engineering.html','engineering.html#projets','boutique.html','demos.html','review.html'):
            document=document.replace(f'href="{target}"',f'href="../{target}"')
    path=R2_OUT/file;path.parent.mkdir(exist_ok=True);path.write_text(document,encoding='utf-8')
